int mga_dma_flush ( struct drm_device * dev , void * data , struct drm_file * file_priv ) { drm_mga_private_t * dev_priv = ( drm_mga_private_t * ) dev -> dev_private ; struct drm_lock * lock = data ; DRM_DEBUG ( "%s%s%s\n" , ( lock -> flags & _DRM_LOCK_FLUSH ) ?"flush, " : "" , ( lock -> flags & _DRM_LOCK_FLUSH_ALL ) ?"flush all, " : "" , ( lock -> flags & _DRM_LOCK_QUIESCENT ) ?"idle, " : "" ) ; WRAP_WAIT_WITH_RETURN ( dev_priv ) ; if ( lock -> flags & ( _DRM_LOCK_FLUSH | _DRM_LOCK_FLUSH_ALL ) ) { mga_do_dma_flush ( dev_priv ) ; } if ( lock -> flags & _DRM_LOCK_QUIESCENT ) { int ret = mga_do_wait_for_idle ( dev_priv ) ; if ( ret < 0 ) { DRM_INFO ( "-EBUSY\n" ) ; } return ret ; return mga_do_wait_for_idle ( dev_priv ) ; } else { return 0 ; } } 